# November 28, 2026: a scatter of twelve National Historic Sites across Ontario, from Lake Erie and the Detroit River
# to Thunder Bay: three iron-works and mill sites, a lighthouse, two museums in old public buildings, a bridge, a
# theatre, a house and a burned church. Region on, claimed with tools/choose.py --thinnest.
# Sources opened: Wikipedia articles, the Parks Canada Directory of Federal Heritage Designations, HistoricPlaces.ca,
# Doors Open Ontario, and the pages of whoever runs each place (Castle Kilbride, the Long Point Region Conservation
# Authority, St. Raphael's Ruins). Hours for the Wellington museum came from a web search result quoting its own site.
from data_b import N
from data_ma import W
def L(t,u): return [t,u]
BATCH={'key':'on_vtqe','label':'Ontario: National Historic Sites scatter','added':'2026-11-28 07:37'}
PLACES=[
N('castle-kilbride-baden','Castle Kilbride','Baden','on','landmark','standing',43.40417,-80.67139,'exact','open','drive','','1877–1878',
  "James Livingston, a Scottish-born flax and linseed-oil manufacturer who was called the Flax and Oil King of Canada, built this Italianate villa in 1877, naming it for his birthplace, East Kilbride. A local man, David Gingerich, built it, and it was finished in 1878. The family sold its contents in 1988 and the house stood empty until the Township of Wilmot bought it in 1993 and restored it. It was designated a National Historic Site in 1995.",
  "A three-storey Italianate house with a belvedere on top and a heart-shaped front lawn, said to honour Livingston's wife. Wikipedia and the township's page both single out the painted interior, with trompe-l'oeil murals in the Italian Renaissance manner. It now serves as a museum and event venue, with original furniture and household items on show.",
  '',
  "Owned by the Township of Wilmot. Address 60 Snyder's Road West, Baden. The township's page says to buy tickets in advance or at the door.",
  [W('Castle Kilbride'),L('Castle Kilbride, Township of Wilmot','https://www.castlekilbride.ca/')],
  hours='Wednesday to Sunday, 10 am to 3 pm; closed Mondays and Tuesdays (township page, November 2026)',
  builder='David Gingerich',archw='Wikipedia: "constructed by a local man, David Gingerich"',brick='?'),
N('capitol-theatre-port-hope','Capitol Theatre, Port Hope','Port Hope','on','civic','standing',43.95099,-78.2931,'exact','open','drive','','1930',
  "Famous Players built this cinema in 1930, after the town's Grand Opera House closed the year before, as one of the first in Canada made for talking pictures. It cost $60,000 and opened on August 15, 1930. The last films ran in 1987 and the seats were taken out; a citizens' foundation formed in 1994 raised money for its restoration and a larger renovation that finished in 2004–2005. It was named a National Historic Site in 2016.",
  "An atmospheric theatre: the auditorium is painted and plastered to look like the courtyard of a Norman castle under a night sky, with castle battlements, hanging vines and clouds thrown on the seamless plaster ceiling by a Brenograph projector. The street front has diamond-paned leaded windows, an original terrazzo floor and an Egyptian-style Capitol sign. Art Deco stencilling shows in the lobby and auditorium. It still shows films and stages live theatre, so the way to see the inside is to buy a ticket.",
  '',
  "Run by a non-profit with staff and volunteers. 20 Queen Street, Port Hope. Opening times are those of the shows; the theatre's page was read but gave no regular hours.",
  [W('Capitol Theatre (Port Hope)'),L('Capitol Theatre','https://www.capitoltheatre.com/')],
  hours='?',arch='Murray Brown',builder='Thomas Garnet and Sons',archw='Wikipedia: designed by Murray Brown, built by Thomas Garnet and Sons',brick='?'),
N('wellington-house-of-industry-fergus','Wellington County House of Industry and Refuge (Wellington County Museum)','Fergus','on','inst','standing',43.69306,-80.39972,'exact','open','drive','','1877–',
  "Wellington County bought the land in 1876 and opened this poorhouse in 1877, the oldest surviving state-supported poorhouse in Canada. It held about 65 people, mostly elderly working-class men, who were meant to farm to earn their keep. It served as a poorhouse until 1947, as an old-age home until 1971, and was made into the Wellington County Museum and Archives in 1987–1988. It became a National Historic Site in 1995.",
  "The main building, with exhibits on the House of Industry and local history. A hospital wing was added in 1893 and a large rear addition in 1955. How much of the original room layout survives was not checked.",
  '',
  "Owned by Wellington County. 0536 Wellington Road 18, Fergus. A web search result quoting the museum's own site gave the hours below and says admission is by donation; the museum's page itself could not be opened, so check before going.",
  [W('Wellington County House of Industry and Refuge'),L('Wellington County Museum and Archives','https://wcma.wellington.ca/')],
  hours='Monday to Friday 9:30 am to 4:30 pm; Saturday and Sunday 11:30 am to 4 pm (not read on the museum page)',brick='?'),
N('canal-lake-concrete-arch-bridge','Canal Lake Concrete Arch Bridge','Bolsover','on','landmark','standing',44.55801,-79.04592,'exact','view','drive','','1905',
  "The federal Department of Railways and Canals built this bridge in 1905 where the Trent–Severn Waterway crosses Canal Lake. It is the earliest known bridge in Canada built of reinforced concrete, using a modified Melan system with curved steel girders inside the concrete. It became a National Historic Site in 1988. It was refurbished between April 2018 and February 2019.",
  "A closed-spandrel concrete arch about 202 ft long and 16 ft wide, high enough for boats to pass under. The spandrel walls are scored to look like cut stone voussoirs and coursed masonry, so a visitor sees a stone-looking bridge made of concrete. A plaque stands on the southwest side. The 2018–2019 work replaced the road deck and refaced the surface, so the finish is new.",
  '',
  "Part of the Trent–Severn Waterway, managed by Parks Canada; the bridge carries a public road, so it can be seen from the road; where to stop and park was not checked.",
  [W('Canal Lake Concrete Arch Bridge'),L('Parks Canada: Trent–Severn Waterway visitor information','https://parks.canada.ca/lhn-nhs/on/trentsevern/visit')],
  brick='no',bcol='none'),
N('barnum-house-grafton','Barnum House','Grafton','on','landmark','standing',43.99083,-78.04361,'exact','view','drive','','1817–1819',
  "Eliakim Barnum, a Loyalist from Vermont, built this house between 1817 and 1819 on land where his brother-in-law's house had burned in the War of 1812. Wikipedia calls it the earliest example of Neoclassical architecture in Canada. The Architectural Conservancy of Ontario bought it in 1939 and restored it as Ontario's first house museum; the Ontario Heritage Trust has owned it since 1982. It was made a National Historic Site in 1959.",
  "A central temple-fronted block with flanking wings, pilasters joined by elliptical arches, and fine woodwork in the parlour and other rooms. The Trust rebuilt the foundation and replaced the cedar roof in 1989–1991, and the collection includes an early Clementi piano. Whether the interior is open now is not known: it was closed from 2003, opened for three months in 2007 and on a limited basis in 2019, and two undated museum listings say it is not open.",
  '',
  "Owned by the Ontario Heritage Trust. The Trust's own page could not be opened, so no hours are given: ask the Trust before going and look from the road meanwhile.",
  [W('Barnum House'),L('Barnum House, Ontario Heritage Trust','https://www.heritagetrust.on.ca/properties/barnum-house')],
  brick='?'),
N('bois-blanc-lighthouse-amherstburg','Bois Blanc Island Lighthouse and Blockhouse','Amherstburg','on','light','standing',42.08694,-83.11944,'exact','boat','boat','','1836–1838',
  "The government of Upper Canada built the limestone lighthouse in 1836 at the south end of Bois Blanc Island, where the Detroit River meets Lake Erie. The Hackett family kept it for nearly ninety years. A fire in 1954 destroyed the lantern, and it was decommissioned in the late 1950s. The blockhouse, the last of three on the island, was built in 1838 to help defend Fort Malden. The site became a National Historic Site in 1955.",
  "A tapered round rubble-stone tower about 18 ft across at the base and 40 ft high, with a stepped corbelled cornice and three windows; its doorway was blocked with rubble after vandals wrecked the door. The wooden blockhouse near it was nearly collapsed by 2010 and was raised on a new concrete foundation, re-floored and given a cedar-shake roof by volunteers, and has artefacts from digs on show. Wikipedia says the tower is closed but the site is open.",
  '',
  "The lighthouse belongs to Parks Canada and the blockhouse is privately owned. The island lies in the Detroit River; how visitors cross to it and when was not checked.",
  [W('Bois Blanc Island Lighthouse and Blockhouse')],
  brick='no',bcol='none'),
N('tourist-pagoda-thunder-bay','Thunder Bay Tourist Pagoda','Thunder Bay','on','landmark','standing',48.43457,-89.21805,'exact','open','walk','','1909',
  "Port Arthur's Industrial Commission held a design competition in 1908 for a striking tourist bureau near the railway station and the waterfront. Local architect H. Russell Halton won, and the Pagoda was built in 1909. Doors Open Ontario calls it Canada's oldest continuously operating tourist information bureau; Wikipedia says it was closed in 1986 and later reopened. It became a National Historic Site in 1986.",
  "A small eclectic building that mixes eastern and western styles. Over the entrance is a stone panel with a beaver and a maple branch, and a gable ends in a small dragon's head said to be a Scandinavian good-luck symbol. The roof was painted with polka dots in 1961, 1973 and 1985. Wikipedia calls the plan hexagonal and Doors Open calls it octagonal. The City of Thunder Bay owns it and Tourism Thunder Bay runs it.",
  '',
  "City-owned, at 170 Red River Road on the waterfront. Doors Open lists full wheelchair access, washrooms and self-guided visits. No opening hours were found.",
  [W('Thunder Bay Tourist Pagoda'),L('Doors Open Ontario: Thunder Bay Tourist Pagoda','https://doorsopenontario.on.ca/thunder-bay/thunder-bay-tourist-pagoda')],
  hours='?',arch='H. Russell Halton',archw='Wikipedia and Doors Open Ontario: design by Harry Russell Halton, winner of a 1908 competition',brick='?'),
N('st-raphaels-ruins-glengarry','St. Raphael\'s Ruins','South Glengarry','on','worship','ruins',45.21154,-74.59686,'exact','open','drive','','1815–1970',
  "St. Raphael's was begun as early as 1815 and its main church finished in 1821, at the heart of a Highland Scottish settlement. Until the 1840s its parish was the largest and most important for English-speaking Catholics in Upper Canada, and Bishop Alexander Macdonell, the first Catholic bishop of Upper Canada, ran his diocese from it in the 1820s. A fire in 1970 left only the walls; they were later stabilized by the Ontario Heritage Foundation. Dates of designation as a National Historic Site vary by source (1996, 1997 and 1999).",
  "Tall ashlar stone walls, roofless, which a conservator described as the finest workmanship and the best monument of its type in Canada. The ruin stands in a church precinct with a burial ground and other church buildings. The site's own page says visitors are welcome free of charge, with donations welcome, and that the gates are open in the daytime in summer.",
  '',
  "Run by a local committee; 19998 County Road 18, Williamstown. The site says it is open to the public seven days a week, with a curator on site Thursday to Monday, 9 am to 5 pm, in summer. Weddings and photography sessions must be booked.",
  [L('Canadian Register of Historic Places: Ruin of St. Raphael\'s Roman Catholic Church','https://www.historicplaces.ca/en/rep-reg/place-lieu.aspx?id=14123'),L('St. Raphael\'s Ruins','https://saintraphaelsruins.com'),L('Doors Open Ontario: St. Raphael\'s Ruins','https://www.doorsopenontario.on.ca/cornwall-and-sdg-counties-1/st-raphaels-ruins')],
  hours='Open daily in summer; curator on site Thursday to Monday, 9 am to 5 pm (site page, undated)',brick='?'),
N('normandale-furnace-site','Normandale Furnace site','Normandale','on','industry','traces',42.7096,-80.30981,'area','view','walk','','1816–1847',
  "John Mason built an ironworks and blast furnace here in 1816–1817 and Joseph Van Norman, Hiram Capron and George Tillson enlarged it in 1821–1822. It made the Van Norman cooking stove, kettles, pots and farm tools, employed up to 200 men, and shut in 1847 when the local bog iron ore ran out. Parks Canada's designation dates are 1818 to 1850; the plaque says 1816–1817 for the start. It was named a National Historic Site in 1927.",
  "Almost nothing. Parks Canada says the foundry has no visible remains on its hillside site apart from slag fragments in the river, and that the site is overgrown with trees. What a visitor will find is a Historic Sites and Monuments Board plaque, recorded by another source in a small park on the north side of Mill Lane.",
  '',
  "A small park and plaque by Mill Lane in the village; the hillside site itself is overgrown and who owns it was not checked, so keep to the park. The pin is the plaque's mapped position, not the furnace.",
  [L('Parks Canada: Normandale Furnace','https://www.pc.gc.ca/apps/dfhd/page_nhs_eng.aspx?id=441'),L('Ontario Plaques: Normandale Blast Furnace','https://ontarioplaques.com/Plaques/Plaque_Norfolk18.html')],
  conf='mixed',brick='?'),
N('lansdowne-iron-works-lyndhurst','Lansdowne Iron Works (Furnace Falls)','Lyndhurst','on','industry','traces',44.54963,-76.12534,'area','view','drive','','1801–1812',
  "Wallis Sunderlin, a Vermont founder, set up the first iron works in Upper Canada at Furnace Falls in 1801, with a furnace for cast iron and a forge for wrought iron. It ran with limited success until a fire destroyed it in 1811. An attempt in 1815–1816 to restart it to supply the Kingston dockyard ended when the powers agreed to limit arms on the Great Lakes. It became a National Historic Site in 1932. The plaque says the works operated until 1811 and the original Ontario plaque says until 1812.",
  "Parks Canada lists the few visible remains as partial sections of foundations and scattered slag, an archaeological site on the east bank of the Gananoque River just below the falls. The federal plaque is beside County Road 33, about 50 m west of the Lyndhurst bridge.",
  '',
  "Who owns the ground with the remains was not checked; treat it as look-from-the-road and use the roadside plaque. The pin is the falls, not a located foundation.",
  [L('Parks Canada: Lansdowne Iron Works','https://www.pc.gc.ca/apps/dfhd/page_nhs_eng.aspx?id=418')],
  conf='mixed',brick='?',apart='lyndhurst-bridge: the bridge is a stone-arch road bridge; the iron works were a furnace and forge on the bank below the falls, a different site that shares the falls as its pin'),
N('backhouse-grist-mill-port-rowan','Backhouse Grist Mill','Port Rowan','on','industry','standing',42.6534,-80.46865,'site','open','drive','','1798',
  "John Backhouse built this water-powered grist mill in 1798, and it ground flour until the family sold the property in 1956 (Wikipedia says the mill ran until 1957). It is one of few Norfolk County mills to survive the War of 1812. Parks Canada made it a National Historic Site in 1998 as a rare surviving example of early grain milling in Upper Canada.",
  "A heavy hand-hewn timber frame with surviving machinery, some of it later 19th and early 20th century, beside a rushing stream. It stands in the Backus Heritage Village, with the 1852 Backus homestead, an octagonal schoolhouse, log cabins, barns, and carriage and blacksmith shops. The Long Point Region Conservation Authority says the mill itself is closed for tours in the 2026 season for structural safety.",
  '',
  "Run by the Long Point Region Conservation Authority at 1267 Second Concession Road. The mill is closed for tours in 2026, but the rest of the historic site is open in the season below.",
  [W('Backus Mill Heritage and Conservation Centre'),L('Long Point Region Conservation Authority: Backhouse Historic Site','https://www.lprca.on.ca/?p=207'),L('Parks Canada: Backhouse Grist Mill','https://pc.gc.ca/apps/dfhd/page_nhs_eng.aspx?id=1852')],
  hours='May 27 to Labour Day weekend, Wednesday to Sunday 11 am to 4 pm; mill closed for tours in 2026',brick='no',bcol='none'),
N('rosamond-woollen-mill-almonte','Rosamond Woollen Mill (Mississippi Valley Textile Museum)','Almonte','on','industry','standing',45.22799,-76.19993,'exact','open','drive','','1866–',
  "B. and W. Rosamond and Company built the Rosamond Woollen Mill on Coleman's Island at the falls of the Mississippi River in 1866. A warehouse was added in 1872 and an office in 1904. In the late 19th century it was the largest woollen mill in Canada, with 74 men, 105 women and 30 youths making tweed worth $350,000 a year, and it ran for 120 years. It became a National Historic Site in 1986, and the Ontario Heritage Trust holds a conservation easement on it.",
  "Long two- and three-storey buildings of grey stone with red-framed windows beside the river. The Mississippi Valley Textile Museum is in part of them, with carding machines and other mill equipment on show; a caption on a Wikimedia Commons photograph says another part of the old mill is now condominiums, and what that covers was not checked. The mill is stone, not brick.",
  '',
  "A museum at 3 Rosamond Street East, Almonte. The town's page for it could not be opened, so no hours are given: check before going.",
  [L('HistoricPlaces.ca: Mississippi Valley Textile Mill','https://historicplaces.ca/en/rep-reg/place-lieu.aspx?id=8881')],
  hours='?',brick='no',bcol='none'),
]
